mapper.sql:
WHERE status <> 2

    AND username LIKE CONCAT(#{keyword}, '%')


    AND status = #{status}

mapper.update:
UPDATE sys_user
SET status = 2,
    updated_by = #{operatorId},
    updated_at = #{now}
WHERE id = #{id}
  AND status <> 2

UPDATE sys_user
SET status = #{status},
    updated_by = #{operatorId},
    updated_at = #{now}
WHERE id = #{id}
  AND status <> 2

UPDATE sys_user
SET password_hash = #{passwordHash},
    must_change_password = #{mustChange},
    updated_by = #{operatorId},
    updated_at = #{now}
WHERE id = #{id}

UPDATE sys_user SET token_version = token_version + 1
, must_change_password = 0
WHERE id = #{id}

UPDATE sys_user
SET role_version = role_version + 1,
    updated_at = #{now}
WHERE id = #{id}

UPDATE sys_user
SET fail_count = fail_count + 1,
    locked_until = CASE
        WHEN fail_count + 1 >= #{threshold} THEN #{lockedUntil}
        ELSE locked_until
    END,
    updated_at = #{now}
WHERE id = #{id}

UPDATE sys_user
SET fail_count = 0,
    locked_until = NULL,
    last_login_at = #{lastLoginAt},
    updated_at = #{now}
WHERE id = #{id}

UPDATE sys_user
SET fail_count = 0,
    locked_until = NULL,
    updated_at = #{now}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM sys_user_role ur
JOIN sys_role r ON r.id = ur.role_id
WHERE ur.user_id = #{userId}
  AND r.code = #{roleCode}
  AND r.status = 1
